<script setup lang="ts">
import {confirmAction} from '../ui/confirm'
import {ref,onMounted} from 'vue'
import {useRouter} from 'vue-router'
import {request} from '../api'
import ReaderShell from '../blog/ReaderShell.vue'
import PrivatePreview from '../admin/PrivatePreview.vue'
type Food={shop_name?:string;address?:string;travel_source?:string|null;id:string;record_id:string;record_revision:number;title:string;name:string;description:string;city:string;city_source:string;category:string;day:string|null;article_date:string;cover_id:string|null;revision:number;source_kind:string;place:{id:string;name:string;city:string;address:string}|null}
const router=useRouter(),items=ref<Food[]>([]),admin=ref(false),q=ref(''),city=ref(''),restaurant=ref(''),category=ref(''),year=ref(''),kind=ref('visits'),sort=ref('newest'),page=ref(1),total=ref(0),busy=ref(false),message=ref(''),editing=ref<Food|null>(null),manualCity=ref(''),manualCategory=ref('')
async function load(){busy.value=true;message.value='';try{const params=new URLSearchParams({q:q.value,city:city.value,category:category.value,kind:kind.value,sort:sort.value,page:String(page.value)});if(year.value)params.set('year',year.value);if(restaurant.value)params.set('place_id',restaurant.value);const d=await request('/food?'+params);items.value=d.items;total.value=d.total}catch(e){message.value=String(e)}finally{busy.value=false}}
async function create(){busy.value=true;try{const t=await request('/admin/food/install-template',{method:'POST'});await router.push('/write?template='+t.id)}catch(e){message.value=String(e)}finally{busy.value=false}}
async function rebuild(){if(!await confirmAction('从现有文章和行程重建派生美食索引？不改原文、地点或图片，人工城市修正保留。'))return;busy.value=true;try{let after='';do{const r=await request('/admin/food/rebuild'+(after?'?after='+after:''),{method:'POST'});after=r.next||''}while(after);await load();message.value='索引已重建，原文和人工城市修正保留'}catch(e){message.value=String(e)}finally{busy.value=false}}
function edit(f:Food){editing.value=f;manualCity.value=f.city;manualCategory.value=f.category}
async function save(reset=false){if(!editing.value)return;busy.value=true;try{await request('/admin/food/occurrences/'+editing.value.id,{method:'PUT',body:JSON.stringify({expected_revision:editing.value.revision,city_override:reset?null:manualCity.value,category:manualCategory.value})});editing.value=null;await load()}catch(e){message.value=String(e)}finally{busy.value=false}}
async function remove(f:Food){if(!await confirmAction('删除来源美食文章「'+f.title+'」？将进入文章回收站；地点、原图与历史仍保留。'))return;busy.value=true;try{await request('/admin/content/records/'+f.record_id,{method:'DELETE',body:JSON.stringify({expected_revision:f.record_revision})});await load()}catch(e){message.value=String(e)}finally{busy.value=false}}
onMounted(async()=>{try{admin.value=(await request('/admin/status')).is_admin}catch{admin.value=false}await load()})
</script>
<template><ReaderShell><template #nav><RouterLink v-if="admin" to="/drafts">我的草稿</RouterLink></template><h1>美食足迹</h1><p>记录餐厅、独立美食和家庭制作。每一次经历都保留，地点和照片复用原资源。</p><div v-if="admin" class="actions"><button :disabled="busy" @click="create">新建美食文章</button><button class="quiet" :disabled="busy" @click="rebuild">重建已有文章索引</button></div><form class="filters" @submit.prevent="page=1;load()"><label>美食 / 餐厅 / 故事<input v-model="q" maxlength="200" type="search"/></label><label>城市<input v-model="city" maxlength="100" placeholder="空白为全部；待分类"/></label><label>分类<input v-model="category" maxlength="100"/></label><label>年份<input v-model="year" type="number" min="1" max="9999"/></label><label>来源视图<select v-model="kind"><option value="visits">美食出现记录（不重复计文章）</option><option value="articles">独立美食文章</option></select></label><label>排序<select v-model="sort"><option value="newest">日期由近到远</option><option value="oldest">日期由远到近</option><option value="name">名称</option></select></label><button :disabled="busy">筛选</button><button v-if="restaurant" type="button" class="quiet" @click="restaurant='';page=1;load()">清除餐厅限定</button></form><p v-if="message" role="status">{{message}}</p><p v-if="busy">正在整理美食记录…</p><p v-else-if="!items.length">暂无匹配的已发布美食。已有旧文章可由管理员重建索引；新文章发布后自动出现。</p><article v-for="f in items" :key="f.id" class="archive-row food-entry"><PrivatePreview v-if="f.cover_id" :id="f.cover_id" :alt="f.name"/><div v-else class="food-no-image" aria-label="暂无明确关联图片">暂无图片</div><div><h2>{{f.source_kind==='article'?f.title:f.name}}</h2><p v-if="f.shop_name" class="food-shop">店铺 · {{f.shop_name}}</p><p v-if="f.address">{{f.address}}</p><p>{{f.day||('就餐日期未明确 · 文章 '+f.article_date)}} · {{f.city||'待分类'}} · {{f.category||'未分类'}}</p><p v-if="f.place">{{f.place.name}} · {{f.place.address||f.place.city}} <button class="quiet" @click="restaurant=f.place.id;page=1;load()">只看这家餐厅 / 分店</button></p><p class="food-description">{{f.description}}</p><RouterLink :to="'/posts/'+f.record_id">{{f.travel_source?'旅行来源：':'阅读文章：'}}{{f.travel_source||f.title}}</RouterLink><div v-if="admin" class="actions"><RouterLink :to="'/write/'+f.record_id">编辑名称、描述、图片与备注</RouterLink><button class="quiet" @click="edit(f)">修正城市 / 分类</button><button v-if="f.source_kind==='article'" class="danger" @click="remove(f)">删除美食文章</button><span v-else>删除单次标记请明确编辑原文；不会静默更改来源。</span></div></div></article><section v-if="editing" role="region" aria-label="修正美食归属"><h2>修正城市与分类</h2><p>只改本次出现，不修改地点库；重建索引后保留。当前来源：{{editing.city_source}}</p><label>城市<input v-model="manualCity" maxlength="100"/></label><label>分类<input v-model="manualCategory" maxlength="100"/></label><button :disabled="busy" @click="save()">保存修正</button><button :disabled="busy" @click="save(true)">恢复来源城市</button><button class="quiet" @click="editing=null">取消</button></section><div class="actions"><button :disabled="busy||page<=1" @click="page--;load()">上一页</button><span>{{page}} · {{total}} 项</span><button :disabled="busy||page*20>=total" @click="page++;load()">下一页</button></div></ReaderShell></template>
<style scoped>.food-entry{display:grid;grid-template-columns:minmax(100px,240px) minmax(0,1fr);gap:24px}.food-no-image{display:grid;place-items:center;aspect-ratio:1.5;background:var(--surface);color:var(--muted);border:1px dashed var(--line);border-radius:var(--radius)}.food-shop{font-size:.9em;color:var(--muted)}.food-entry :deep(img){width:100%;height:auto;max-height:220px;object-fit:cover}.food-description{white-space:pre-wrap;line-height:1.8}@media(max-width:600px){.food-entry{grid-template-columns:1fr;gap:12px}}</style>
